  "apps.lightplanCopy": { es: "Coloca y organiza elementos eléctricos, iluminación, domótica, seguridad y climatización sobre un plano. Incluye capas y exportación.", en: "Place and organize electrical, lighting, smart-home, security and climate-control elements on a floor plan, with layers and exports." },
  "apps.crm": { es: "CRM interno para equipos", en: "Internal team CRM" },
  "apps.crmCopy": { es: "Un sistema de gestión de clientes, oportunidades, agenda y seguimiento, diseñado alrededor del proceso de un equipo de reformas.", en: "A customer, opportunity, calendar and follow-up system shaped around a home renovation team's workflow." },
  "apps.budget": { es: "Presupuestos de obra", en: "Renovation estimates" },
  "apps.budgetCopy": { es: "Herramienta para preparar y revisar presupuestos con partidas, costes y control de cambios adaptados al trabajo de reformas.", en: "A tool for preparing and reviewing renovation estimates, line items, costs and changes." },
  "apps.disclaimer": { es: "Estas piezas se presentan como muestras visuales. No son demos funcionales y no muestran información personal o de clientes.", en: "These projects are visual showcases only. They are not functional demos and do not display client or personal information." },
  "faq.title": { es: "Preguntas claras. Decisiones mejores.", en: "Clear answers. Better decisions." },
  "faq.eyebrow": { es: "08 / Preguntas frecuentes", en: "08 / Frequently asked questions" },
  "faq.intro": { es: "Lo que conviene saber antes de iniciar una web, solicitar una propuesta o completar el briefing.", en: "What to know before starting a website, requesting a proposal or completing the project briefing." },
  "faq.all": { es: "Ver todas las preguntas", en: "Browse all questions" },
  "faq.q1": { es: "¿Cómo funciona el plazo de 24-48 horas?", en: "How does the 24-48 hour timeline work?" },
  "faq.a1": { es: "Se refiere a la primera versión de una landing cubierta por la propuesta. El reloj empieza cuando el pago, el briefing y los materiales necesarios están completos. Si Waika no cumple ese plazo, devuelve el 50% del importe cubierto. No es una promesa de publicación final en ese mismo plazo.", en: "It applies to the first version of a landing page covered by the proposal. The clock starts when payment, the briefing and required materials are complete. If Waika misses that deadline, 50% of the covered fee is refunded. It is not a promise of final publication within that same window." },
  "faq.q2": { es: "¿Cómo se calcula el presupuesto de mi web?", en: "How is my website estimate calculated?" },
  "faq.a2": { es: "La landing de una página parte de $250, con dominio y hosting incluidos durante el primer año. Las páginas y funciones adicionales suman importes estimativos en el presupuestador; el alcance y el precio final se confirman por escrito.", en: "A one-page landing starts at $250, including domain and hosting for the first year. Additional pages and features add indicative amounts in the quote builder; the final scope and price are confirmed in writing." },
  "faq.q3": { es: "¿El precio incluye dominio y alojamiento?", en: "Are domain and hosting included?" },
  "faq.a3": { es: "La landing base incluye el dominio y el hosting durante el primer año. Las renovaciones posteriores y los servicios de terceros pueden generar costes adicionales y se detallan en la propuesta.", en: "The base landing page includes domain and hosting for the first year. Later renewals and third-party services may add costs, which are detailed in the proposal." },
  "faq.q4": { es: "¿Puedo pedir una aplicación o un CRM a medida?", en: "Can I request a custom app or CRM?" },
  "faq.a4": { es: "Sí. Primero estudiamos el proceso, los usuarios y las integraciones necesarias. Después preparamos un presupuesto específico. No publicamos un precio cerrado sin conocer el alcance.", en: "Yes. We first assess the workflow, users and required integrations, then prepare a project-specific quote. We do not publish a fixed price without understanding the scope." },
  "faq.q5": { es: "¿Qué ocurre después de enviar el briefing?", en: "What happens after I send the briefing?" },
  "faq.a5": { es: "El briefing se envía a nuestro flujo interno para organizar la información del proyecto. Revisamos las respuestas y nos ponemos en contacto para aclarar el alcance y preparar los siguientes pasos.", en: "Your briefing goes to our internal workflow so we can organize the project information. We review it and follow up to clarify scope and agree on next steps." },
  "faq.q6": { es: "¿Gestionan redes sociales y crean contenido?", en: "Do you manage social media and create content?" },
  "faq.a6": { es: "La gestión de redes empieza en $250. La frecuencia, las piezas y el alcance se detallan en la propuesta. Los paquetes de creación de contenido se están definiendo; consúltanos para valorar el formato adecuado.", en: "Social media management starts at $250. Frequency, assets and scope are specified in the proposal. Content-creation packages are still being defined; contact us to discuss the right format." },
  "faq.q7": { es: "¿Puedo solicitar asesoría?", en: "Can I book a consultation?" },
  "faq.a7": { es: "Sí, la asesoría puede contratarse por hora. Confirmaremos la tarifa y el formato antes de reservar.", en: "Yes, consulting can be booked by the hour. We confirm the rate and format before booking." },
