function waikaText(key, locale = document.documentElement.lang) {
  return waikaCopy[key]?.[locale === "en" ? "en" : "es"] || key;
}

function addSharedControls() {
  if (document.querySelector("[data-site-ui]")) return;
  const shared = document.createElement("div");
  shared.dataset.siteUi = "true";
  shared.innerHTML = `
    <div class="site-dock" role="group" aria-label="Accesos rápidos">
      <button type="button" class="site-dock-toggle" data-dock-toggle aria-expanded="false" aria-controls="site-dock-actions" aria-label="Accesos rápidos" title="Accesos rápidos"><svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="5" cy="12" r="1"/><circle cx="12" cy="12" r="1"/><circle cx="19" cy="12" r="1"/></svg></button>
      <div class="site-dock-actions" id="site-dock-actions">
        <button type="button" data-chat-open aria-expanded="false" aria-controls="waika-chat" aria-label="Abrir el asistente" title="Abrir el asistente"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M20 11.5a7.5 7.5 0 0 1-7.8 7.5 8.4 8.4 0 0 1-3.7-.9L4 19l1-4a7.3 7.3 0 0 1-.9-3.5A7.6 7.6 0 0 1 12 4a7.6 7.6 0 0 1 8 7.5Z"/><path d="M8.5 11.5h7M8.5 14.5h4"/></svg></button>
        <button type="button" data-language aria-label="Cambiar idioma" title="Cambiar idioma">EN</button>
        <button type="button" data-back-top aria-label="Volver arriba" title="Volver arriba"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="m5 14 7-7 7 7M12 7v13"/></svg></button>
      </div>
    </div>
    <section class="chat-panel" id="waika-chat" aria-labelledby="chat-title" aria-modal="false" hidden>
      <header class="chat-head"><strong id="chat-title">Asistente Waika</strong><button type="button" data-chat-close aria-label="Cerrar asistente">×</button></header>
      <div class="chat-messages" role="log" aria-live="polite" aria-relevant="additions text"><p class="chat-message" data-chat-intro></p></div>
      <form class="chat-form" data-chat-form><label class="sr-only" for="chat-input">Escribe tu pregunta</label><textarea id="chat-input" name="message" maxlength="1200" required></textarea><button type="submit">Enviar</button></form>
    </section>
    <aside class="cookie-banner" role="region" aria-labelledby="cookie-title" hidden>
      <p><strong id="cookie-title">Tu privacidad, primero.</strong><br><span data-cookie-message></span></p>
      <div class="cookie-actions"><button type="button" data-cookie-reject></button><button type="button" data-cookie-accept></button><button type="button" data-cookie-settings></button></div>
    </aside>
    <dialog class="cookie-dialog" aria-labelledby="cookie-dialog-title">
      <form method="dialog" data-cookie-form>
        <h2 id="cookie-dialog-title">Preferencias de privacidad</h2>
        <div class="cookie-setting"><div><strong data-cookie-necessary-label></strong><p data-cookie-necessary-help></p></div><input type="checkbox" checked disabled aria-label="Siempre activas"></div>
        <label class="cookie-setting"><div><strong data-cookie-analytics-label></strong><p data-cookie-analytics-help></p></div><input type="checkbox" name="analytics" data-cookie-analytics></label>
        <label class="cookie-setting"><div><strong data-cookie-marketing-label></strong><p data-cookie-marketing-help></p></div><input type="checkbox" name="marketing" data-cookie-marketing></label>
        <div class="cookie-dialog-actions"><button type="button" data-cookie-only-necessary></button><button type="button" data-cookie-cancel></button><button type="button" data-cookie-save></button></div>
      </form>
    </dialog>`;
  document.body.append(shared);
}

function translateLegalPage(locale) {
  const article = document.querySelector("article.legal-copy");
  if (!article) return;
  const english = locale === "en";
  const path = location.pathname.replace(/\/$/, "");
  const insertEmail = (element, before, after) => {
    const link = document.createElement("a");
    link.href = "mailto:waikastudios@gmail.com";
    link.textContent = "waikastudios@gmail.com";
    element.replaceChildren(document.createTextNode(before), link, document.createTextNode(after));
  };
  const title = article.querySelector("h1");
  const intro = article.querySelector(".page-intro > p");
  const headings = [...article.querySelectorAll(":scope > h2")];
  const paragraphs = [...article.querySelectorAll(":scope > p")];

  if (path === "/privacidad") {
    if (title) title.textContent = english ? "Privacy notice." : "Aviso de privacidad.";
    if (intro) intro.textContent = english
      ? "What data we receive when you contact Waika Studios and how we use it to respond to a project enquiry."
      : "Qué datos recibimos cuando contactas con Waika Studios y cómo los usamos para atender una solicitud de proyecto.";
    const headingText = english
      ? ["Data controller", "What we process and why", "Legal basis", "Providers and workflow", "Retention", "Your rights", "Scope of this version"]
      : ["Responsable", "Qué datos tratamos y para qué", "Base jurídica", "Proveedores y flujo de trabajo", "Conservación", "Tus derechos", "Alcance de esta versión"];
    headings.forEach((element, index) => { if (headingText[index]) element.textContent = headingText[index]; });
    const text = english ? [
      null,
      "Your project brief may include your name, contact email and the information you provide about your business, goals, materials, references and dates. We use it to respond, understand the scope and prepare next steps or a proposal.",
      "We process the information to take the pre-contractual steps you request by submitting the brief. If another use is proposed later, we will explain it separately and identify the applicable legal basis.",
      "The site sends project briefs to the Make automation workflow, which may create a document in Google Drive and prepare a prompt with Anthropic. Questions to the assistant are also sent to Anthropic to generate a response. Do not enter passwords, payment details or sensitive personal information.",
      "Before public launch, the specific providers and subprocessors, processing locations and safeguards for international transfers must be verified. The chat tool may remain disabled until this review is complete.",
      "A draft brief is stored in your browser for up to 48 hours and you can delete it manually. If the browser remains open, it is removed when that period expires; if it is closed earlier, expiry is cleaned up when the form is loaded again. Waika must set the final retention period for received enquiries in its internal schedule before launch.",
      null,
      "This notice describes the planned workflow for the project brief and assistant. The final version must identify the controller with its registered details and confirm provider, retention and transfer information before the form is opened to the public."
    ] : [
      null,
      "El briefing puede incluir nombre, correo de contacto y la información que facilites sobre tu negocio, objetivos, materiales, referencias y fechas. Se usa para responder a tu solicitud, entender el alcance y preparar los siguientes pasos o una propuesta.",
      "La información se trata para atender las medidas precontractuales que solicitas al enviar el briefing. Si más adelante se propone otro uso, se explicará por separado y se pedirá la base jurídica que corresponda.",
      "El sitio remite el briefing al flujo de automatización de Make, que puede generar un documento en Google Drive y preparar un prompt con Anthropic. Las consultas al asistente también se envían a Anthropic para producir una respuesta. No introduzcas contraseñas, datos de pago ni información personal sensible.",
      "Antes del lanzamiento deben verificarse los proveedores y subencargados concretos, ubicación del tratamiento y garantías aplicables a transferencias internacionales. La herramienta de chat puede permanecer desactivada hasta completar esa revisión.",
      "El borrador del briefing se guarda en el navegador con una caducidad de 48 horas y puedes borrarlo manualmente. Si el navegador permanece abierto, se elimina al vencer ese plazo; si se cierra antes, la caducidad se limpia cuando el formulario vuelve a cargarse. El periodo definitivo de conservación de las solicitudes recibidas por Waika debe fijarse en el calendario interno antes del lanzamiento.",
      null,
      "Este aviso describe el flujo previsto para el briefing y el asistente. La versión definitiva debe identificar al responsable con sus datos registrales y confirmar los detalles de proveedores, conservación y transferencias antes de abrir el formulario al público."
    ];
    paragraphs.forEach((element, index) => {
      if (index === 0) {
        insertEmail(element,
          english ? "Waika Studios. Privacy contact: " : "Waika Studios. Contacto de privacidad: ",
          english ? ". The controller's legal name and postal address will be added before the site is published on its final domain." : ". La razón social y dirección postal del responsable se incorporarán antes de publicar el sitio en el dominio definitivo.");
      } else if (index === 6) {
        insertEmail(element,
          english ? "You may request access, correction, deletion, objection, restriction or portability where applicable by writing to " : "Puedes solicitar acceso, rectificación, supresión, oposición, limitación o portabilidad, cuando corresponda, escribiendo a ",
          english ? ". You may also lodge a complaint with the competent data protection authority." : ". También puedes presentar una reclamación ante la autoridad de protección de datos competente.");
      } else if (text[index]) element.textContent = text[index];
    });
  } else if (path === "/terminos") {
    if (title) title.textContent = english ? "Terms of use." : "Condiciones de uso.";
    if (intro) intro.textContent = english
      ? "Information about this website and how Waika Studios services are presented."
      : "Información sobre este sitio y la forma de presentar los servicios de Waika Studios.";
    const headingText = english
      ? ["Website information", "Proposals and engagement", "First-version timeline", "Intellectual property", "Contact"]
      : ["Información del sitio", "Propuestas y contratación", "Plazo de primera versión", "Propiedad intelectual", "Contacto"];
    headings.forEach((element, index) => { if (headingText[index]) element.textContent = headingText[index]; });
    const text = english ? [
      "This website presents Waika Studios services, projects and indicative prices. The public information describes general scope; it does not replace a specific proposal or service agreement.",
      "Before work starts, the scope, final price, applicable taxes, materials, schedule, revisions, hosting and any relevant third-party services are agreed in writing. Custom app and software estimates depend on reviewing the workflow and required integrations.",
      "For a landing page included in the proposal, the 24–48 business-hour period starts once payment, the brief and required materials are complete. If Waika misses that deadline, 50% of the covered amount is refunded under the proposal's specific terms. This is not a promise of final publication and does not include later revision rounds.",
      "Projects shown link to their original websites. Their names, brands, copy and images belong to their respective owners. Displaying a work as a portfolio example does not transfer rights to use that content.",
      null
    ] : [
      "Este sitio presenta servicios, proyectos y precios orientativos de Waika Studios. La información pública ayuda a describir el alcance general; no sustituye una propuesta específica ni un acuerdo de servicio.",
      "Antes de empezar, se acuerdan por escrito el alcance, precio final, impuestos aplicables, materiales, calendario, revisiones, alojamiento y servicios de terceros que correspondan. El presupuesto de aplicaciones y software a medida depende del estudio del proceso y de las integraciones necesarias.",
      "Para la landing incluida en la propuesta, el plazo de 24-48 horas laborables comienza cuando se han completado el pago, el briefing y los materiales necesarios. Si Waika incumple ese plazo, se devuelve el 50% del importe cubierto, de acuerdo con las condiciones concretas de la propuesta. El plazo no equivale a publicación final ni incluye rondas posteriores de cambios.",
      "Los proyectos mostrados enlazan a sus sitios originales. Los nombres, marcas, textos e imágenes de esos sitios pertenecen a sus respectivos titulares. El uso de una obra como muestra del portafolio no transfiere derechos de uso sobre esos contenidos.",
      null
    ];
    paragraphs.forEach((element, index) => {
      if (index === 4) {
        insertEmail(element,
          english ? "For questions about this website or its services: " : "Para consultas sobre este sitio o los servicios: ",
          english ? ". Complete legal terms will be added alongside the registered identity before launch on the final domain." : ". Las condiciones legales completas se incorporarán junto con la identidad registral antes del lanzamiento en el dominio definitivo.");
      } else if (text[index]) element.textContent = text[index];
    });
  } else if (path === "/cookies") {
    if (title) title.textContent = english ? "Cookies and preferences." : "Cookies y preferencias.";
    if (intro) intro.textContent = english
      ? "Choose which options to save. Optional features are not activated just because you visit this page."
      : "Elige qué opciones guardar. Las funciones opcionales no se activan por el mero hecho de visitar esta página.";
    const headingText = english
      ? ["Current site status", "Local brief storage", "Preferences", "Manage or withdraw your choice"]
      : ["Estado actual del sitio", "Almacenamiento local del briefing", "Preferencias", "Gestionar o retirar tu elección"];
    const text = english ? [
      "No analytics or advertising tool is currently loaded. The site uses browser storage to remember your language, cookie preferences and, while completing the brief, your answers on that device.",
      "The draft is saved only in the browser where you write it and expires after 48 hours. You can delete it from the project-brief page. The local copy is removed when the brief is sent.",
      "The preference controls let you accept or reject analytics and marketing options. As these tools are not installed yet, no optional script loads even if you accept. If added in the future, your choice will be applied before they are activated.",
      "Return to this page or open the preference controls in the site footer to change the choice saved in your browser."
    ] : [
      "Actualmente no se carga una herramienta de analítica ni de publicidad. La web usa almacenamiento local del navegador para recordar el idioma, las preferencias de cookies y, durante el briefing, tus respuestas en ese dispositivo.",
      "El borrador se guarda solo en el navegador donde lo escribes y caduca a las 48 horas. Puedes borrarlo desde la propia página del briefing. Al enviarlo, la copia local se elimina.",
      "El control de preferencias permite aceptar o rechazar opciones de analítica y marketing. Como estas herramientas aún no están instaladas, no se carga ningún script opcional aunque aceptes. Si se incorporan en el futuro, la elección se aplicará antes de activarlas.",
      "Puedes volver a esta página o abrir el control de preferencias en el pie del sitio para modificar la decisión guardada en tu navegador."
    ];
    headings.forEach((element, index) => { if (headingText[index]) element.textContent = headingText[index]; });
    paragraphs.forEach((element, index) => { if (text[index]) element.textContent = text[index]; });
  }
}

